from core import *
def pct(z):return f'{z:.2f}'.replace('.',',')
def delta(p,k):return f"{pct(100*p['micro'][k])} п.п. [{pct(100*p['ci'][0][k])}; {pct(100*p['ci'][1][k])}]"
def main():
    r=read(D/'results.json');p=r['panels']['outside204'];m=p['arms'];c=p['paired'];a=c['dpp minus qwen'];h=c['history minus dpp_mask'];n=r['panels']['neural12'];raw=read(D/'reranker-scores.json.gz')
    names={'qwen':'Qwen3-Embedding-8B','dpp':'DPP, β=0,8','mmr':'Попарный штраф MMR','dpp_05':'DPP, β=0,5','dpp_095':'DPP, β=0,95',
        'qwen_mask':'Qwen, просмотренное в конце','mmr_mask':'MMR с отсрочкой','dpp_mask':'DPP с отсрочкой','historic_static':'Статическая поправка на историю','history':'DPP с условием на историю'}
    table=['| Метод | MSS@5 | MSS@8 | MSS@8, 2 048 | MSS, 2 048 без лимита единиц | MSS, 6 144 без лимита единиц | GroupRecall@5 | NEC@5 |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for name,nm in names.items():
        z=m[name];s=z['sum'];table.append(f"| {nm} | {int(s[0])} | {int(s[1])} | {int(s[2])} | {int(s[7])} | {int(s[8])} | {pct(100*z['mean'][4])}% | {pct(100*z['mean'][6])}% |")
    ab=r['panels']['outside204_seen'];t=c['dpp minus mmr'];z=r['panels']['all214']['arms']
    neural=n['arms'];nn=n['paired']['neural minus qwen'];cfg=read(D/'reranker-seal.json');lens=[a for rec in raw.values() for a in rec['token_roundtrips']]
    runtime=read(D/'runtime-audit.json');costs=runtime['prompt_tokens'];f=read(D/'forecast-seal.json')
    fr=[f"На 204 ранее удержанных состояниях 69 репозиториев без маски просмотренного жадная DPP собрала полный набор среди первых пяти фрагментов в **{int(m['dpp']['sum'][0])}/204** случаях. Исходный Qwen3-Embedding-8B дал **{int(m['qwen']['sum'][0])}/204**. MSS засчитывается, если в выдаче есть полный достаточный набор свидетельств. Первичная разница **{delta(a,0)}**, выигрышей {a['wins'][0]}, потерь {a['loss'][0]}, число состояний с изменившимся составом первых пяти фрагментов — {a['changed_set5']}. При равном весе каждому репозиторию разность {pct(100*a['macro'][0])} п.п. [{pct(100*a['macro_ci'][0][0])}; {pct(100*a['macro_ci'][1][0])}]. [Протокол](PROTOCOL_RU.md) · [Численные результаты](results.json)",
     "Детерминантная выдача уменьшает ценность документа в той мере, в какой его словарное представление уже объясняется всем выбранным набором. Попарный контроль использует только максимальное сходство с одним выбранным документом. Для обоих методов неизменны исходные Qwen-ранги, первое выбранное свидетельство, BPE-текст и ядро сходства. Формула относится к существующей литературе DPP. Приоритетность памяти проверяет отдельная абляция с предварительной проекцией на уже прочитанные единицы. [Алгоритм DPP](https://proceedings.neurips.cc/paper/2018/hash/dbbf603ff0e99629dda5d75b6f75f966-Abstract.html)","\n".join(table),
     f"При восьми фрагментах без маски DPP теряет относительно Qwen {int(m['qwen']['sum'][1]-m['dpp']['sum'][1])} полных наборов из 204, разность {delta(a,1)}. Для этого дополнительного показателя интервал номинальный, поправка на множество сравнений не применялась. Разность между совместным и попарным штрафом на MSS@5 составляет {delta(t,0)}. После одинаковой отсрочки просмотренных фрагментов предварительное условие на истории меняет состав top-5 в {h['changed_set5']} случаях. Разность MSS@5 составляет {delta(h,0)}. В {ab['states']} состояниях, где наблюдавшиеся фрагменты действительно представлены в пуле, разница {delta(ab['paired']['history minus dpp_mask'],0)}. В остальных состояниях проверка показала одинаковый полный порядок у двух DPP. На всех 214 состояниях счёт основной пары {int(z['dpp']['sum'][0])} против {int(z['qwen']['sum'][0])}.",
     f"При 2 048 токенах и допуске глубже восьми единиц DPP и одиночная Qwen отдают в среднем {pct(m['dpp']['items'][4])} и {pct(m['qwen']['items'][4])} единицы, расходуют {pct(m['dpp']['tokens'][4])} и {pct(m['qwen']['tokens'][4])} токена. При 6 144 средний расход {pct(m['dpp']['tokens'][5])} и {pct(m['qwen']['tokens'][5])}. Верхние пределы и последовательный префикс совпадают для всех методов. При превышении остатка читатель останавливается. Доступ к большему числу коротких единиц изменяет содержательную интерпретацию сравнения с фиксированным @8.",
     "Проверяемое предположение о преимуществе DPP при пяти фрагментах осталось неподтверждённым. В основной точке сходство со всеми ранее выбранными фрагментами дало тот же счёт, что и попарный штраф. Условие на уже наблюдённых фрагментах принесло дополнительные потери. Среди будущих кандидатов для статьи стоит проверить общность роли, которую фрагменты выполняют в решении. Лексическое различие само по себе позволяет выбрать несколько фрагментов с одной и той же ролью. Эта интерпретация требует самостоятельной проверки.\n\n## Что показал реальный cross-encoder",
     f"Для независимо от исходов выбранных двенадцати состояний разных репозиториев модель Qwen3-Reranker-0.6B (Q4_K_M) оценила 192 пары из первых 16 кандидатов Qwen3-Embedding-8B на CPU. При пяти единицах счёт {int(neural['neural']['sum'][0])}/12 у cross-encoder, {int(neural['qwen']['sum'][0])}/12 у первоначального Qwen и {int(neural['dpp_top16']['sum'][0])}/12 у DPP, ограниченной ровно теми же 16 кандидатами. При восьми единицах соответственно {int(neural['neural']['sum'][1])}, {int(neural['qwen']['sum'][1])} и {int(neural['dpp_top16']['sum'][1])}. Разность cross-encoder минус embedding на MSS@5 {delta(nn,0)}, выигрышей {nn['wins'][0]}, потерь {nn['loss'][0]}. Общая длительность CPU-прогона {pct(cfg['elapsed']/60)} мин. Сервер обработал {costs:,} входных токенов, число усечённых пар {runtime['truncated_pairs']}. Это независимо подтверждают журнал вычислительных слотов и счётчики API. Из {len(lens)} декодированных текстов запроса/документов {sum(x==y==z for x,y,z in lens)} полностью совпали при повторной токенизации. [Протокол подпанели](RERANK_PROTOCOL_RU.md) · [Оценки каждой пары](reranker-scores.json.gz)",
     f"Официальный результат MSS-Complement на скрытом Test500 — 73,0%/80,6%, комбинации двух 8B-моделей — 61,4%/72,4%. Наше исследование проверяет иной публичный набор и в подпанели другой размер модели и глубину ранжирования. Аудит 74 опубликованных путей и 12 реальных JSON подтверждает доступность агрегатов и позволяет проверить границы такого сравнения. Сравнивать локальные проценты с закрытой строкой как свидетельство нового SOTA нельзя. Независимый пересчёт сверил опубликованный алгоритм с прямыми детерминантами на шести состояниях. Измеренное время формирования всех полных рангов и контролей {pct(f['elapsed'])} с, отдельно от исходных эмбеддингов. [Аудит и первоисточники](REFERENCES_RU.md) · [Воспроизведение](REPRODUCE_RU.md)"]
    (D/'REPORT_RU.md').write_text('# Помогает ли наборная выдача поверх сильного семантического ранжирования\n\n'+'\n\n'.join(fr).replace('159,162','159 162')+'\n',encoding='utf8')
if __name__=='__main__':main()
